Section BSM.
  Variables (RNG : footprint) (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t6 : word) (F : bvmap 5 word) (fc : bv 32)
            (m : amem) (D S : Z) (bs : list Z) (lo : Z) (junk8 : list byte).
  Hypothesis SPD : bv_unsigned sp <= D.
  Hypothesis D8 : D mod 8 = 0.
  Hypothesis DH : D + 48 <= 2^47.
  Hypothesis BS : ablk S (S + zlen bs).
  Hypothesis S8 : S + 8 <= 2^47.
  Hypothesis BOT : ATOP + 4096 <= lo.
  Hypothesis LO : lo <= bv_unsigned sp - 2240.
  Hypothesis BY : Forall (fun c => 0 <= c < 256) bs.
  Hypothesis HN : 1 <= zlen bs <= 7.
  Hypothesis ZD : zshadow m D 40.
  Hypothesis US : unpoisoned m S (S + zlen bs).
  Hypothesis RD : rng RNG D 40.
  Hypothesis RDs : rng RNG (shad D) (nshad (40 + D mod 8)).
  Hypothesis RS : rng RNG S (zlen bs).
  Hypothesis RSs : rng RNG (shad S) (nshad (zlen bs + S mod 8)).
  Hypothesis RSTK : rng RNG lo (bv_unsigned sp - lo).
  Hypothesis AW : appW [(bv_unsigned sp - 2240, bv_unsigned sp); (D, D + 40)].

  Definition ST_bs (pc : Z) (m1 : amem) (x5 x6 x7 x13 x14 x16 x17 x28 x29 x30 : word) : machine_state :=
    MS (mkR ra (Z_to_bv 64 (bv_unsigned sp + -16)) gp tp x5 x6 x7 s0 s1 (Z_to_bv 64 D) (Z_to_bv 64 S) (Z_to_bv 64 (zlen bs))
            x13 x14 (Z_to_bv 64 2147450880) x16 x17 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 x28 x29 x30 t6)
       F (Z_to_bv 64 pc) fc None m1 (seg_rom asegs).

  Definition BS_PRE (m1 : amem) (c : Z) (j8 : list byte) : Prop :=
    munch [(bv_unsigned sp - 2240, bv_unsigned sp); (D, D + 40)] m m1 /\ wmono asegs m m1 /\ mem_inv asegs m1
    /\ rw_cells asegs m1 (bv_unsigned sp + -16) [CB 8 junk8; C8 ra] /\ stk asegs m1 lo (bv_unsigned sp + -16)
    /\ rw_cells asegs m1 D [C8 (Z_to_bv 64 c); CB 8 j8; C8 (Z_to_bv 64 S); C8 (Z_to_bv 64 S); C8 (Z_to_bv 64 (S + 8))]
    /\ bytes_at asegs m1 S (map (Z_to_bv 8) bs).

  Notation POSTB := (bit_init_postA ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc D S bs lo m).

  (* [comment removed for export] *)
  Lemma bs_fin : forall m1 c j8 (x5 x6 x7 x13 x14 x16 x17 x28 x29 x30 : word),
    BS_PRE m1 c j8 -> c = lesmall bs ->
